#!/usr/bin/env node
/**
 * P-C5-4 live migration proof (owner-approved public npm reads; no publish,
 * auth, mutation, or deprecation pointer).
 *
 * Consumes the single authoritative migration map
 * (`docs/migrations/c5-migration-map.json`, generated by
 * `generate-c5-migration-map.mjs`). Steps:
 *   1. Query BOTH scopes (require exit 0); confirm the old scope latest < 1.0.
 *   2. Equality guard: the map's C5-owned old names equal the before-surface
 *      Thenvoi exports (deleting a map row fails here).
 *   3. Pack the real last-supported 0.x and the current 1.0 candidate.
 *   4. Build ONE old consumer (root + every subpath + EVERY mapped value/type +
 *      every option member), transform it through the map, assert no legacy
 *      identifier remains.
 *   5. tsc-COMPILE (NodeNext, emit) AND EXECUTE old vs 0.x and migrated vs
 *      candidate, ESM and CJS.
 *   6. Red-check: a missing export fails to compile.
 *
 * Usage: node scripts/c5-migration-fixture.mjs
 */
import { readFileSync, writeFileSync, mkdtempSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { resolve, join, dirname } from "node:path";
import { tmpdir } from "node:os";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sdkRoot = resolve(repoRoot, "packages/sdk");
const migDir = resolve(repoRoot, "docs/migrations");
const pkg = JSON.parse(readFileSync(join(sdkRoot, "package.json"), "utf-8"));
const map = JSON.parse(readFileSync(join(migDir, "c5-migration-map.json"), "utf-8"));
const before = JSON.parse(readFileSync(join(migDir, "c5-surface-before-70a2822.json"), "utf-8"));
const OLD = map.package.old;
const NEW = map.package.new;
const tsc = join(sdkRoot, "node_modules/.bin/tsc");
// Only members present in the packed 0.x participate in the live migration.
// Source-C4-only members (renamed after the published 0.x) are proven by the
// dedicated C4-tip source compile test instead.
const publishedMembers = map.members.filter((m) => m.provenance === "published-0x");

function run(cmd, args, opts = {}) {
  const r = spawnSync(cmd, args, { encoding: "utf8", ...opts });
  return { status: r.status ?? 1, out: (r.stdout ?? "") + (r.stderr ?? "") };
}
function must(label, r) {
  if (r.status !== 0) { console.error(`FAIL: ${label}\n${r.out}`); process.exit(1); }
  console.log(`ok: ${label}`);
}
function fail(msg) { console.error(`FAIL: ${msg}`); process.exit(1); }

function migrate(text) {
  let out = text.split(OLD).join(NEW);
  const syms = [...map.symbols].sort((a, b) => b.old.length - a.old.length);
  for (const s of syms) out = out.replace(new RegExp(`\\b${s.old}\\b`, "g"), s.new);
  for (const m of publishedMembers) out = out.replace(new RegExp(`\\b${m.memberOld}\\b`, "g"), m.memberNew);
  return out;
}

function oldConsumer() {
  const subs = Object.keys(pkg.exports);
  const lines = [];
  for (const s of subs) lines.push(`import ${JSON.stringify(OLD + (s === "." ? "" : s.slice(1)))};`);
  const valueBySpec = new Map();
  const typeBySpec = new Map();
  for (const s of map.symbols) {
    const spec = OLD + (s.subpath === "." ? "" : s.subpath.slice(1));
    (s.kind === "value" ? valueBySpec : typeBySpec).set(spec, [...( (s.kind === "value" ? valueBySpec : typeBySpec).get(spec) ?? [] ), s.old]);
  }
  for (const [spec, names] of valueBySpec) lines.push(`import { ${[...new Set(names)].join(", ")} } from ${JSON.stringify(spec)};`);
  for (const [spec, names] of typeBySpec) lines.push(`import type { ${[...new Set(names)].join(", ")} } from ${JSON.stringify(spec)};`);
  // option-member owners not otherwise imported (interface names unchanged)
  const ownerImports = new Map();
  publishedMembers.forEach((m) => {
    const spec = OLD + (m.subpath === "." ? "" : m.subpath.slice(1));
    if (!map.symbols.some((s) => s.old === m.ownerOld)) ownerImports.set(spec, [...(ownerImports.get(spec) ?? []), m.ownerOld]);
  });
  for (const [spec, names] of ownerImports) lines.push(`import type { ${[...new Set(names)].join(", ")} } from ${JSON.stringify(spec)};`);
  publishedMembers.forEach((m, i) => lines.push(`type _M${i} = ${m.ownerOld}["${m.memberOld}"];`));
  map.symbols.filter((s) => s.kind === "type").forEach((s, i) => lines.push(`type _Ty${i} = ${s.old};`));
  const values = map.symbols.filter((s) => s.kind === "value").map((s) => s.old);
  lines.push(`for (const v of [${values.join(", ")}]) { if (typeof v !== "function" && typeof v !== "object") throw new Error("value missing at runtime"); }`);
  lines.push(`export const _ok = true as const;`);
  return lines.join("\n") + "\n";
}

const work = mkdtempSync(join(tmpdir(), "c5-mig-"));
try {
  // 1. query BOTH scopes (require exit 0)
  const oldQ = run("npm", ["view", OLD, "version"]);
  const bandQ = run("npm", ["view", NEW, "version"]);
  if (oldQ.status !== 0) fail(`npm view ${OLD} failed:\n${oldQ.out}`);
  if (bandQ.status !== 0) fail(`npm view ${NEW} failed:\n${bandQ.out}`);
  const oldVer = oldQ.out.trim();
  const bandVer = bandQ.out.trim();
  console.log(`scopes: ${OLD}@${oldVer} | ${NEW}@${bandVer}`);
  if (!(Number(oldVer.split(".")[0]) < 1)) fail(`${OLD} latest ${oldVer} is not < 1.0`);
  console.log(`ok: ${OLD} latest ${oldVer} < 1.0`);

  // 2. equality guard: map C5 old names == before-surface Thenvoi exports
  const beforeThenvoi = new Set();
  for (const e of Object.values(before.subpaths)) {
    for (const n of [...e.runtime, ...e.declarations]) if (n.includes("Thenvoi")) beforeThenvoi.add(n);
  }
  const mapC5Old = new Set(map.symbols.filter((s) => !s.c3).map((s) => s.old));
  const missing = [...beforeThenvoi].filter((n) => !mapC5Old.has(n));
  const extra = [...mapC5Old].filter((n) => !beforeThenvoi.has(n));
  if (missing.length || extra.length) fail(`map C5 rows != before surface Thenvoi exports (missing ${missing}, extra ${extra})`);
  console.log(`ok: map covers all ${beforeThenvoi.size} C5 before-surface Thenvoi exports (+${map.symbols.filter((s) => s.c3).length} C3, ${map.members.length} members)`);

  // 3. pack old 0.x + candidate
  must("pack old 0.x", run("npm", ["pack", `${OLD}@${oldVer}`, "--pack-destination", work]));
  const oldTgz = readdirSync(work).find((f) => f.endsWith(".tgz"));
  must("pack candidate", run("npm", ["pack", "--ignore-scripts", "--pack-destination", work], { cwd: sdkRoot }));
  const candTgz = readdirSync(work).find((f) => f.endsWith(".tgz") && f !== oldTgz);

  // 4. build + transform the single fixture
  const oldSrc = oldConsumer();
  const migSrc = migrate(oldSrc);
  for (const bad of [OLD, "Thenvoi", ...publishedMembers.map((m) => m.memberOld)]) {
    if (migSrc.includes(bad)) fail(`migrated fixture still contains "${bad}"`);
  }
  console.log("ok: migrated fixture has no @thenvoi/sdk import or legacy identifier");

  // 5. install peers + both packages, compile + execute
  mkdirSync(join(work, "proj"));
  writeFileSync(join(work, "proj/package.json"), JSON.stringify({ name: "c5-consumer", private: true, version: "1.0.0", type: "module" }));
  const peers = Object.entries(pkg.peerDependencies || {}).map(([n, r]) => `${n}@${r}`);
  must("install peers + both SDKs", run("npm", ["install", "--no-audit", "--no-fund", "--loglevel=error", `${OLD}@${oldVer}`, resolve(work, candTgz), ...peers], { cwd: join(work, "proj") }));

  // applicability: every published-0x member's OLD member must actually be
  // declared in the packed 0.x. Misclassifying a source-c4 member as
  // published-0x fails here (its old member is absent from the real 0.x).
  const oldPkgDir = join(work, "proj/node_modules", OLD);
  const oldDts = readdirSync(oldPkgDir, { recursive: true })
    .map(String)
    .filter((f) => f.endsWith(".d.ts") || f.endsWith(".d.cts"))
    .map((f) => readFileSync(join(oldPkgDir, f), "utf-8"))
    .join("\n");
  for (const m of publishedMembers) {
    if (!new RegExp(`\\b${m.memberOld}\\b`).test(oldDts)) {
      fail(`published-0x member ${m.ownerOld}.${m.memberOld} is not declared in ${OLD}@${oldVer}; provenance misclassified (should be source-c4)`);
    }
  }
  console.log(`ok: all ${publishedMembers.length} published-0x members are declared in ${OLD}@${oldVer}`);

  for (const [name, src] of [["old.mts", oldSrc], ["old.cts", oldSrc], ["mig.mts", migSrc], ["mig.cts", migSrc]]) {
    writeFileSync(join(work, "proj", name), src);
  }
  writeFileSync(join(work, "proj/tsconfig.json"), JSON.stringify({
    compilerOptions: { module: "nodenext", moduleResolution: "nodenext", target: "es2022", outDir: "build", strict: true, skipLibCheck: true, esModuleInterop: true, typeRoots: [join(sdkRoot, "node_modules/@types")] },
    include: ["old.mts", "old.cts", "mig.mts", "mig.cts"],
  }));
  must("tsc compile old + migrated (ESM + CJS), all 21 rows + members", run(tsc, ["-p", "tsconfig.json"], { cwd: join(work, "proj") }));
  must("execute OLD ESM", run(process.execPath, ["build/old.mjs"], { cwd: join(work, "proj") }));
  must("execute OLD CJS", run(process.execPath, ["build/old.cjs"], { cwd: join(work, "proj") }));
  must("execute MIGRATED ESM", run(process.execPath, ["build/mig.mjs"], { cwd: join(work, "proj") }));
  must("execute MIGRATED CJS", run(process.execPath, ["build/mig.cjs"], { cwd: join(work, "proj") }));

  // 6. red-check
  writeFileSync(join(work, "proj/bad.mts"), `import { NoSuchExportXyz } from ${JSON.stringify(NEW)};\nexport const _x = NoSuchExportXyz;\n`);
  writeFileSync(join(work, "proj/tsconfig.bad.json"), JSON.stringify({ compilerOptions: { module: "nodenext", moduleResolution: "nodenext", target: "es2022", noEmit: true, strict: true, skipLibCheck: true }, include: ["bad.mts"] }));
  if (run(tsc, ["-p", "tsconfig.bad.json"], { cwd: join(work, "proj") }).status === 0) fail("red-check missing-export compiled unexpectedly");
  console.log("ok: red-check missing export fails to compile");

  const sourceOnly = map.members.length - publishedMembers.length;
  console.log(`\nP-C5-4 PASS: ${OLD}@${oldVer} -> ${NEW}@${bandVer} candidate — one fixture migrated via the authoritative map (${map.symbols.length} symbols + ${publishedMembers.length} published-0x members; ${sourceOnly} source-c4 member(s) excluded, proven by the C4-tip source compile test), tsc-compiled AND executed for ESM+CJS across ${Object.keys(pkg.exports).length} subpaths.`);
} finally {
  rmSync(work, { recursive: true, force: true });
}
